import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"58、【兑】 兑下兑上","description":"周易尚氏学 - 58、【兑】 兑下兑上","frontmatter":{"title":"58、【兑】 兑下兑上","description":"周易尚氏学 - 58、【兑】 兑下兑上"},"headers":[],"relativePath":"zh/classics/shangshi/063.md","filePath":"zh/classics/shangshi/063.md"}'),h={name:"zh/classics/shangshi/063.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_58、【兑】-兑下兑上" tabindex="-1">58、【兑】 兑下兑上 <a class="header-anchor" href="#_58、【兑】-兑下兑上" aria-label="Permalink to “58、【兑】 兑下兑上”">​</a></h1><p>兑悦也。兑何以悦。以一阴见于二阳之上。阳得阴而悦也。刚中柔外。与泰义合。故亨。阴阳相遇。故利贞。</p><p>彖曰。兑。说也。刚中而柔外。说以利是以顺乎天而应乎人。说以先民。民忘其劳。说以犯难。民志其死。说之大。民功矣哉。</p><p>阴阳相遇故悦。悦故利贞。所谓保合太和。各正性命也。五天位。上顺之。故日顺乎天。互巽为顺也。三人位。巽于二。故日应乎人。互巽为应也。三至上大坎。坎为民。为劳。为险难。为棺郭（左木）。故为死。而三至上正反兑。坎民来往。皆在兑说之中。故役之而忘劳。犯难而不知死也。兑见在上。故曰先民。先民说。先使民悦也。故民劝。</p><p>象曰。丽泽兑。君子以朋友讲习。</p><p>玉篇丽偶也。周礼夏官校人。丽马一口（内辛）。注丽耦也。又士冠礼。主人酬宾。束帛。俪皮。注俪皮两鹿皮。古文俪作离。离传云。离而也。是丽一俪通仍耦也。重兑故曰丽泽。犹重巽日随风。其以互离为义者。非也。阴阳相遇相悦为朋友。兑口故曰购习。初至五正反兑相对。正朋友互相讲习之象。故君子法之。虞翻谓兑二阳同类为朋。夫阳遇阳。阴遇阴。则为害为敌。昆与中孚皆言之。岂得为朋友。又云伏艮为友。盖取义于损六三。一人行则得其友。岂知艮之为友。以一阳上行。遇二阴为友。与兑之以一阴下降。遇二阳为朋友同。皆取义于阴阳相遇。朋友之诂既误。于是卦无艮兑而言朋者。必百计变动以求兑象。甚至用参同契纳甲之法。谓八日兑象月见了。以解坤彖之得朋。凡易之言朋者。无不误矣。</p><p>初九。和兑，吉。</p><p>与二并行。故曰和。当位故吉。初与二本为敌。卦以兑说为义。和以处之。自然吉矣。</p><h3 id="象曰。和兑之吉。行未疑也。" tabindex="-1">象曰。和兑之吉。行未疑也。 <a class="header-anchor" href="#象曰。和兑之吉。行未疑也。" aria-label="Permalink to “象曰。和兑之吉。行未疑也。”">​</a></h3><p>初得敌。故疑于二。和以处之。故行不疑。损三云。三则疑也。易于阳遇阳相疑相忌之故。言之至为明白矣。乃失传何哉。</p><p>九二。孚兑吉。悔亡。</p><p>孚于三。阳遇阴故吉。得中。故悔亡。</p><h3 id="象曰。孚兑之吉。信志也。" tabindex="-1">象曰。孚兑之吉。信志也。 <a class="header-anchor" href="#象曰。孚兑之吉。信志也。" aria-label="Permalink to “象曰。孚兑之吉。信志也。”">​</a></h3><p>阳遇阴故志得伸。巽为志。三巽主爻。二遇之。故信志。</p><p>六三。来兑凶。</p><p>在内称来。来就二阳以为悦。行为不正则有之。无所谓凶。但三本多凶。又不当位。来而不正遂不宜矣。</p><h3 id="象曰。来兑之凶。位不当也。" tabindex="-1">象曰。来兑之凶。位不当也。 <a class="header-anchor" href="#象曰。来兑之凶。位不当也。" aria-label="Permalink to “象曰。来兑之凶。位不当也。”">​</a></h3><p>来而不当位。故凶。</p><p>九四。商兑未宁。介疾有喜。</p><p>四不当位。无应。前又遇阳。似不吉。然而有喜者。以下履阴也。小畜九五曰有孚。履九四曰志行。皆以下遇阴而吉。此与之同。商量度也。商兑者以初至五正反兑相对。而四若与下对语者。故曰商兑。讲习之象。亦以此也。三至五巽。进退不果。故未宁。互大坎为疾。乃四独履阴。志行。是疾去也。介助也。诗以介眉寿是也。介疾有喜者。言助疾使愈。兑悦故有喜也。</p><h3 id="象曰。九四之喜。有庆也。" tabindex="-1">象曰。九四之喜。有庆也。 <a class="header-anchor" href="#象曰。九四之喜。有庆也。" aria-label="Permalink to “象曰。九四之喜。有庆也。”">​</a></h3><p>九四独履阴。履阴故有喜。故曰有庆。</p><p>九五。孚于剥。有厉。</p><p>阳遇阴则通。故二五皆孚于三上。然吉凶不同者。兑为秋。六三当正秋。万物成熟。故二孚之而吉。若上六则为季秋。其辰在戌。其卦为剥。杂卦云。剥烂也。当此时万物荒落。阳气为阴所剥将尽矣。九五若再享于是。必为所剥无疑也。故曰有厉。</p><h3 id="象曰。孚于剥。位正当也。" tabindex="-1">象曰。孚于剥。位正当也。 <a class="header-anchor" href="#象曰。孚于剥。位正当也。" aria-label="Permalink to “象曰。孚于剥。位正当也。”">​</a></h3><p>以人事言。上六处悦之极。是小人佞悻之尤。九五当人君之位。而见近此等小人。其为祸有不可胜言者。象曰位正当。言正当人君之位。不可与上六近也。</p><p>上六。引兑。引。</p><p>开弓视的也。伏艮为手。故引兑。言上六来就五阳以为悦。犹射者之志于的也。</p><h3 id="象曰。上六引兑。未光也。" tabindex="-1">象曰。上六引兑。未光也。 <a class="header-anchor" href="#象曰。上六引兑。未光也。" aria-label="Permalink to “象曰。上六引兑。未光也。”">​</a></h3><p>兑门（内音）昧。故未光。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
